INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "お！\nあそこに困ってそうな人発見！", "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 1, 2, 0, 1.4, 1001, "春咲 ひより", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "大切な人を\n守れるようになりたい…って", "みんなみたいに\nわたしも強くならなきゃ", "わ、わたし、\nなに言ってるんだろ\nあはは…", 1, 2, 0, 1.4, 1002, "草野 優衣", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "キミに必要な集中力と感性が", "フェンシングを始めてみては？", "少しは磨かれると思いますよ。", 1, 2, 0, 1.4, 1003, "士条 怜", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "今日はなにして遊ぶ？", "ねぇ、にいちゃん！", "みそぎはねぇ、\nかくれんぼやりたい！", 1, 2, 0, 1.5, 1004, "穂高 みそぎ", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "ねぇ…", "風宮あかりです", "私といっしょに…\nいかない？", 1, 2, 0, 1.4, 1006, "風宮 あかり", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "プリンたべたいのー", "出雲宮子なのー", "食べ物の恨みは怖いのー", 1, 2, 0, 1.5, 1007, "出雲 宮子", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "キミもボクの美貌に\n吸い寄せられたんだね。", "ボクは虹村雪。", "いいよ。\n見られることは運命さ…", 1, 2, 0, 1.4, 1008, "虹村 雪", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", "フッ…聞いて後悔するがいい！", "人呼んで「疾風の冥姫」!!", 1, 2, 0, 1.4, 1009, "柊杏奈", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", "マホマホ王国のプリンセス、\nまほ姫どす", "ほんまおおきにやわ～♪", 1, 2, 0, 1.5, 1010, "姫宮 真歩", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "生き別れたお兄ちゃんを探して\n三千世界！", "衣之咲璃乃です！", "ここで会ったが\n100年目～！", 1, 2, 0, 1.4, 1011, "衣之咲 璃乃", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "ち、超能力って…\n何のことかな～？", "私はハツネ、\n結構強いんだよ。\nきらーん☆", "…って、お願い！\n誰にも言わないでおいて～！", 1, 2, 0, 1.4, 1012, "柏崎 初音", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "一応カリスマ読モJKやってまっす！", "ちょす！\n美波鈴奈だよ～♪", "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 1, 2, 0, 1.4, 1016, "美波 鈴奈", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "東京は遊園地みたいなところさー", "はいたーい。\n喜屋武香織さー。", "でも、沖縄もとってもいいとこさー", 1, 2, 0, 1.4, 1017, "喜屋武 香織", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "先生って呼ばれるのは\nくすぐったいから", "支倉伊緒です。", "イオちゃんって呼んでね。", 1, 2, 0, 1.4, 1018, "支倉 伊緒", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "あ！/\お兄ちゃ～ん\nまってよ～", "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", "ミミをおいてかないでぇ～", 1, 2, 0, 1.5, 1020, "茜 ミミ", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "あの……\nふぇ……", "あ…あの…えっと…\n栗…林…くるみ…です……", "ふぇぇぇぇぇん……", 1, 2, 0, 1.5, 1021, "栗林 くるみ", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "こんな私に貴重な時間を\n割いていただき、", "風宮よりです。\nあああああ！", "なんてありがとうございます！", 1, 2, 0, 1.4, 1022, "風宮 より", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "おにいちゃんどこいくの？\nえ？", "私、アヤネ！\nぷうきちと一緒についてってあげるね！", "私こっち行きたいー\nね、早く早くー", 1, 2, 0, 1.5, 1023, "北条 綾音", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "ふ、不束者ですが\nどうぞ末永く…って、", "わっ…わっ…私、\n天野すずめといいます！", "これて何か違う…\nあああすみません！", 1, 2, 0, 1.4, 1025, "天野 すずめ", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "あなたは…運命の……\n伴侶……", "……クスクス…私は\n…倉石恵理子……", "離しませんわ………\n絶対に…!!", 1, 2, 0, 1.4, 1027, "倉石 恵理子", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", "…そうでしょ？？", 1, 2, 0, 1.4, 1028, "佐々木 咲恋", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "ぇっと…\nキミ、私のこと知らないの?!", "桜井望だよ！\nよろしくねっ", "あはは、\n私もまだまだだなぁ～", 1, 2, 0, 1.4, 1029, "桜井 望", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "初めまして、\n私はニノン・ジュベール申すデス！", "デケデケデンっ！", "ショーグン、\nワタシと一緒に天下統一デース！", 1, 2, 0, 1.4, 1030, "ニノン・ジュベール", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "でもって私の隣にいるのが……\nえ、見えない？", "上喜しのぶです。\n手元のドクロが父です。", "おかしいですね……", 1, 2, 0, 1.4, 1031, "上喜 しのぶ", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "けんども\nそれには足りないモンが…", "目指すはビッグな\nお笑い芸人だっぺ！", "そう、\nオラのボケに突っ込める相方が…！", 1, 2, 0, 1.5, 1033, "野戸まひる", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "ちょっと緊張しちゃって…", "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", "ちょ\nちょっと一杯飲んできます…！", 1, 2, 0, 1.4, 1034, "綾瀬 ゆかり", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "知らない人とは話しちゃいけないので", "氷川鏡華…です", "これ以上お話しすることは…\nないです！", 1, 2, 0, 1.5, 1036, "氷川 鏡華", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "……あ、アラーム。", "柏崎…栞です。", "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 1, 2, 0, 1.4, 1038, "柏崎 栞", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "私、一人も友達がいなくて……", "ふ、双葉碧です。", "野に咲く花が、\n唯一の話相手です。", 1, 2, 0, 1.4, 1040, "双葉 碧", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", "三角千歌です。", "そう思っています。", 1, 2, 0, 1.4, 1042, "三角 千歌", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "あぁ？\nお前のそいつの仲間か？", "安芸真琴だ。", "う、疑ってすまなかったな…", 1, 2, 0, 1.4, 1043, "安芸 真琴", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "生けとし生ける全ての者よ！", "わらわこそは夜を総べる者！", "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 1, 2, 0, 1.4, 1044, "イリヤ・オーンスタイン", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "ぐふふふふ……はっ！", "そこで騎士は妖精を乱暴に……", "ｌク、クウカに何かご用ですか!?", 1, 2, 0, 1.4, 1045, "遠見 空花", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "自由気ままで♪\n寝て遊んで、食べてケンカして…", "宮坂たまきにゃ♪\n猫はいいにゃよ？", "う～ん…\n猫ってホントに最高にゃ～♪", 1, 2, 0, 1.4, 1046, "宮坂たまき", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "それでは早速クエストに…", "大神美冬よ！", "…と思ったら\nバイトの時間だ！\nまたあとでね！", 1, 2, 0, 1.4, 1048, "大神 美冬", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "クエストもバトルも\n掃除も洗濯も", "星野静流だよ！", "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 1, 2, 0, 1.4, 1049, "星野静流", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "見ての通りの\nセクシー美少女で", "アタシは玉泉美咲。", "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 1, 2, 0, 1.5, 1050, "玉泉美咲", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "？？？？", "？？？", "？？？？", 1, 2, 0, 1.4, 1052, "リマ", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィントだ。", "そ、そこまでいうなら\nもらってやる", 1, 2, 0, 1.5, 1053, "モニカ・ヴァイスヴィント", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィントだ。", "そ、そこまでいうなら\nもらってやる", 1, 2, 0, 1.5, 1058, "ペコリーヌ", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィントだ。", "そ、そこまでいうなら\nもらってやる", 1, 2, 0, 1.5, 1059, "コッコロ", 0, 0, 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 1, "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィントだ。", "そ、そこまでいうなら\nもらってやる", 1, 2, 0, 1.5, 1060, "キャル", 0, 0, 0, 0);
